42: public class SloopLauncher {
43:   public static final String SLOOP_CLI_ENTRYPOINT_CLASS = "org.sonarsource.sonarlint.core.backend.cli.SonarLintServerCli";
44:   private final SonarLintRpcClientDelegate rpcClient;
45:   private final Function<List<String>, ProcessBuilder> processBuilderFactory;
46:   private final Supplier<String> osNameSupplier;
47: 
48:   public SloopLauncher(SonarLintRpcClientDelegate rpcClient) {
49:     this(rpcClient, ProcessBuilder::new, () -> System.getProperty("os.name"));
50:   }
51: 
52:   SloopLauncher(SonarLintRpcClientDelegate rpcClient, Function<List<String>, ProcessBuilder> processBuilderFactory, Supplier<String> osNameSupplier) {
53:     this.rpcClient = rpcClient;
54:     this.processBuilderFactory = processBuilderFactory;
55:     this.osNameSupplier = osNameSupplier;
56:   }
57: 
58:   public Sloop start(Path distPath) {
59:     return start(distPath, null);
60:   }
61: 
62:   public Sloop start(Path distPath, @Nullable Path jrePath) {
63:     return start(distPath, jrePath, null);
64:   }
65: 
66:   /**
67:    * @param jvmOpts Each argument should be separated by a space, such as '-XX:+UseG1GC -XX:MaxHeapFreeRatio=50'
68:    */
69:   public Sloop start(Path distPath, @Nullable Path jrePath, @Nullable String jvmOpts) {
70:     try {
71:       return execute(distPath, jrePath, jvmOpts);
72:     } catch (Exception e) {
73:       logToClient(LogLevel.ERROR, "Unable to start the SonarLint backend", stackTraceToString(e));
74:       throw new IllegalStateException("Unable to start the SonarLint backend", e);
75:     }
76:   }
77: 
78:   private static String stackTraceToString(Throwable t) {
79:     var stringWriter = new StringWriter();
80:     var printWriter = new PrintWriter(stringWriter);
81:     t.printStackTrace(printWriter);
82:     return stringWriter.toString();
83:   }
84: 
85:   /**
86:    * Inspired from Apache commons-lang3
87:    */
88:   private boolean isWindows() {
89:     var osName = osNameSupplier.get();
90:     if (osName == null) {
91:       return false;
92:     }
93:     return osName.startsWith("Windows");
94:   }
95: 
96:   private Sloop execute(Path distPath, @Nullable Path jrePath, @Nullable String jvmOpts) throws IOException {
97:     var jreHomePath = jrePath == null ? distPath.resolve("jre") : jrePath;
98:     logToClient(LogLevel.INFO, "Using JRE from " + jreHomePath, null);
99:     var binDirPath = jreHomePath.resolve("bin");
100:     var jreJavaExePath = binDirPath.resolve("java" + (isWindows() ? ".exe" : ""));
101:     if (!Files.exists(jreJavaExePath)) {
102:       throw new IllegalArgumentException("The provided JRE path does not exist: " + jreJavaExePath);
103:     }
104:     var processBuilder = processBuilderFactory.apply(createCommand(distPath, jreJavaExePath, jvmOpts));
105:     processBuilder.directory(binDirPath.toFile());
106:     processBuilder.redirectOutput(ProcessBuilder.Redirect.PIPE);
107:     processBuilder.redirectInput(ProcessBuilder.Redirect.PIPE);
108:     processBuilder.redirectError(ProcessBuilder.Redirect.PIPE);
109: 
110:     var process = processBuilder.start();
111: 
112:     // redirect process.getErrorStream() to the client logs
113:     new StreamGobbler(process.getErrorStream(), stdErrLogConsumer()).start();
114:     // use process.getInputStream() as an input for the client
115:     var serverToClientInputStream = process.getInputStream();
116:     // use process.getOutputStream() as the standard input of a subprocess that can be written to
117:     var clientToServerOutputStream = process.getOutputStream();
118:     var clientLauncher = new ClientJsonRpcLauncher(serverToClientInputStream, clientToServerOutputStream, rpcClient);
119:     process.onExit().thenAccept(p -> clientLauncher.close());
120: 
121:     var serverProxy = clientLauncher.getServerProxy();
122:     return new Sloop(serverProxy, process);
123:   }
124: 
125:   private static List<String> createCommand(Path distPath, Path jreJavaExePath, @Nullable String clientJvmOpts) {
126:     var libFolderPath = distPath.resolve("lib");
127:     var classpath = libFolderPath.toAbsolutePath().normalize() + File.separator + '*';
128:     List<String> commands = new ArrayList<>();
129:     commands.add(jreJavaExePath.toAbsolutePath().normalize().toString());
130:     var sonarlintEnvJvmOpts = System.getenv("SONARLINT_JVM_OPTS");
131:     if (sonarlintEnvJvmOpts != null) {
132:       commands.addAll(Arrays.asList(sonarlintEnvJvmOpts.split(" ")));
133:     }
134:     if (clientJvmOpts != null) {
135:       commands.addAll(Arrays.asList(clientJvmOpts.split(" ")));
136:     }
137:     // Avoid displaying the Java icon in the taskbar on Mac
138:     commands.add("-Djava.awt.headless=true");
139:     commands.add("-classpath");
140:     commands.add(classpath);
141:     commands.add(SLOOP_CLI_ENTRYPOINT_CLASS);
142:     return commands;
143:   }
144: 
145:   private Consumer<String> stdErrLogConsumer() {
146:     return s -> logToClient(LogLevel.ERROR, "StdErr: " + s, null);
147:   }
148: 
149:   private void logToClient(LogLevel level, @Nullable String message, @Nullable String stacktrace) {
150:     rpcClient.log(new LogParams(level, message, null, Thread.currentThread().getName(),
151:       SloopLauncher.class.getName(), stacktrace, Instant.now()));
152:   }
153: 
154:   private static class StreamGobbler extends Thread {
155:     private final InputStream inputStream;
156:     private final Consumer<String> consumer;
157: 
158:     public StreamGobbler(InputStream inputStream, Consumer<String> consumer) {
159:       this.inputStream = inputStream;
160:       this.consumer = consumer;
161:     }
162: 
163:     @Override
164:     public void run() {
165:       new BufferedReader(new InputStreamReader(inputStream)).lines()
166:         .forEach(consumer);
167:     }
168:   }
169: }

