35: public class ProcessWrapperFactory {
36:   private static final SonarLintLogger LOG = SonarLintLogger.get();
37: 
38:   public ProcessWrapperFactory() {
39:     // nothing to do
40:   }
41: 
42:   public ProcessWrapper create(@Nullable Path baseDir, Consumer<String> lineConsumer, String... command) {
43:     return new ProcessWrapper(baseDir, lineConsumer, command);
44:   }
45: 
46:   public static class ProcessWrapper {
47: 
48:     private final Path baseDir;
49:     private final Consumer<String> lineConsumer;
50:     private final String[] command;
51: 
52:     ProcessWrapper(@Nullable Path baseDir, Consumer<String> lineConsumer, String... command) {
53:       this.baseDir = baseDir;
54:       this.lineConsumer = lineConsumer;
55:       this.command = command;
56:     }
57: 
58:     void processInputStream(InputStream inputStream, Consumer<String> stringConsumer) throws IOException {
59:       try (var reader = new BufferedReader(new InputStreamReader(inputStream, UTF_8))) {
60:         String line;
61:         while ((line = reader.readLine()) != null) {
62:           stringConsumer.accept(line);
63:         }
64:       }
65:     }
66: 
67:     public ProcessExecutionResult execute() {
68:       Process p;
69:       try {
70:         p = createProcess();
71:       } catch (IOException e) {
72:         LOG.warn(format("Could not execute command: [%s]", join(" ", command)), e);
73:         return new ProcessExecutionResult(-2);
74:       }
75:       try {
76:         return runProcessAndGetOutput(p);
77:       } catch (InterruptedException e) {
78:         LOG.warn(format("Command [%s] interrupted", join(" ", command)), e);
79:         Thread.currentThread().interrupt();
80:       } catch (Exception e) {
81:         LOG.warn(format("Command failed: [%s]", join(" ", command)), e);
82:       } finally {
83:         p.destroy();
84:       }
85:       return new ProcessExecutionResult(-1);
86:     }
87: 
88:     Process createProcess() throws IOException {
89:       return new ProcessBuilder()
90:         .command(command)
91:         .directory(baseDir != null ? baseDir.toFile() : null)
92:         .start();
93:     }
94: 
95:     ProcessExecutionResult runProcessAndGetOutput(Process p) throws InterruptedException, IOException {
96:       processInputStream(p.getInputStream(), lineConsumer);
97:       processInputStream(p.getErrorStream(), line -> {
98:         if (!line.isBlank()) {
99:           LOG.debug(line);
100:         }
101:       });
102:       int exit = p.waitFor();
103:       return new ProcessExecutionResult(exit);
104:     }
105:   }
106: 
107:   public record ProcessExecutionResult(int exitCode) {
108:   }
109: }

