29: import static org.apache.commons.lang3.ArrayUtils.reverse;
30: 
31: public class WindowsShortcutUtils {
32:   // Based on Windows specification the magic number is 0x0000004C that must be tested with both big and little endian
33:   // as it might differ based on the architecture / OS.
34:   private static final byte[] WINDOWS_SHORTCUT_MAGIC_NUMBER = new byte[] {0, 0, 0, 76};
35:   
36:   private WindowsShortcutUtils() {
37:     // utility class
38:   }
39: 
40:   /**
41:    *  Checks whether a file provided by URI is a Windows shortcut or not. These differ from actual (sym)links on
42:    *  Windows as they are like an object containing the pointer to the other resource instead of pointing to the
43:    *  resource directly.
44:    */
45:   public static boolean isWindowsShortcut(URI uri) {
46:     // Based on the Windows specification the shortcuts have this file suffix, when changing the file suffix they won't
47:     // work anymore. So if users would create a shortcut, then rename it and have it in the scope of SonarLint this
48:     // would fail but that is fine.
49:     if (!uri.toString().contains(".lnk")) {
50:       return false;
51:     }
52:     
53:     // If the filename ends with ".lnk" we check the magic number in order to determine it to actually be a windows
54:     // shortcut. This is expensive and therefore will actually only do it on files that match this filter!
55:     var magicNumber = new byte[4];
56:     try (var is = new FileInputStream(new File(uri))) {
57:       if (is.read(magicNumber) != magicNumber.length) {
58:         // We can only read 0-3 bytes, therefore it cannot be a Windows shortcut. No idea what kind of file this might
59:         // be (e.g. a text file with 3 characters?) but hey, they gave it a ".lnk" suffix and mimicked a shortcut so
60:         // they probably know better.
61:         return false;
62:       }
63:       
64:       // Check big endian
65:       if (Arrays.equals(WINDOWS_SHORTCUT_MAGIC_NUMBER, magicNumber)) {
66:         return true;
67:       }
68: 
69:       // Check little endian
70:       reverse(magicNumber);
71:       return Arrays.equals(WINDOWS_SHORTCUT_MAGIC_NUMBER, magicNumber);
72:     } catch (IOException err) {
73:       SonarLintLogger.get().debug("Cannot check whether '" + uri + "' is a Windows shortcut, assuming it is not.");
74:     }
75:     
76:     return false;
77:   }
78: }

