29: public class NativeGitLocator {
30:   private static final SonarLintLogger LOG = SonarLintLogger.get();
31:   // So we only have to make the expensive call once (or at most twice) to get the native Git executable
32:   private boolean checkedForNativeGitExecutable = false;
33:   private NativeGit nativeGitExecutable = null;
34: 
35:   /**
36:    * Get the native Git executable by checking for the version of both `git` and `git.exe`. We cache this information
37:    * to not run these expensive processes more than once (or twice in case of Windows).
38:    */
39:   public Optional<NativeGit> getNativeGitExecutable() {
40:     if (checkedForNativeGitExecutable) {
41:       return Optional.ofNullable(nativeGitExecutable);
42:     }
43: 
44:     var nativeGit = getGitExecutable()
45:       .map(NativeGit::new)
46:       .filter(NativeGit::isSupportedVersion);
47:     checkedForNativeGitExecutable = true;
48:     nativeGitExecutable = nativeGit.orElse(null);
49:     return nativeGit;
50:   }
51: 
52:   Optional<String> getGitExecutable() {
53:     return SystemUtils.IS_OS_WINDOWS ? locateGitOnWindows() : Optional.of("git");
54:   }
55: 
56:   private static Optional<String> locateGitOnWindows() {
57:     var lines = new ArrayList<String>();
58:     var result = callWhereTool(lines::add);
59:     return locateGitOnWindows(result, String.join("\n", lines));
60:   }
61: 
62:   static Optional<String> locateGitOnWindows(ProcessWrapperFactory.ProcessExecutionResult result, String lines) {
63:     // Windows will search current directory in addition to the PATH variable, which is unsecure.
64:     // To avoid it we use where.exe to find git binary only in PATH.
65: 
66:     if (result.exitCode() == 0 && lines.contains("git.exe")) {
67:       var out = Arrays.stream(lines.split(System.lineSeparator())).map(String::trim).findFirst();
68:       LOG.debug("Found git.exe at {}", out);
69:       return out;
70:     }
71:     LOG.debug("git.exe not found in PATH. PATH value was: " + System.getProperty("PATH"));
72:     return Optional.empty();
73:   }
74: 
75:   private static ProcessWrapperFactory.ProcessExecutionResult callWhereTool(Consumer<String> lineConsumer) {
76:     LOG.debug("Looking for git command in the PATH using where.exe (Windows)");
77:     return new ProcessWrapperFactory()
78:       .create(null, lineConsumer, "C:\\Windows\\System32\\where.exe", "$PATH:git.exe")
79:       .execute();
80:   }
81: }

