54: public class HttpClientProvider {
55:   private static final SonarLintLogger LOG = SonarLintLogger.get();
56:   private static final int DEFAULT_MAX_RETRIES = 2;
57:   private static final int DEFAULT_RETRY_INTERVAL = 3;
58: 
59:   private final CloseableHttpAsyncClient sharedClient;
60:   private final ExecutorService webSocketThreadPool;
61:   private final String userAgent;
62: 
63:   /**
64:    * Return an {@link HttpClientProvider} made for testing, with a dummy user agent, and basic configuration regarding proxy/SSL
65:    */
66:   public static HttpClientProvider forTesting() {
67:     return new HttpClientProvider("SonarLint tests", new HttpConfig(new SslConfig(null, null), null, null, null, null), null, ProxySelector.getDefault(),
68:       new BasicCredentialsProvider());
69:   }
70: 
71:   public HttpClientProvider(String userAgent, HttpConfig httpConfig, @Nullable Predicate<TrustManagerParameters> trustManagerParametersPredicate, ProxySelector proxySelector,
72:     CredentialsProvider proxyCredentialsProvider) {
73:     this.userAgent = userAgent;
74:     this.webSocketThreadPool = FailSafeExecutors.newCachedThreadPool(threadWithNamePrefix("sonarcloud-websocket-"));
75:     var maxRetries = Integer.parseInt(System.getProperty("sonarlint.http.max.retries", String.valueOf(DEFAULT_MAX_RETRIES)));
76:     var retryInterval = Integer.parseInt(System.getProperty("sonarlint.http.retry.interval.seconds", String.valueOf(DEFAULT_RETRY_INTERVAL)));
77:     sharedClient = buildSharedClient(userAgent, httpConfig, trustManagerParametersPredicate, proxySelector, proxyCredentialsProvider, maxRetries, retryInterval);
78:     sharedClient.start();
79:   }
80: 
81:   private static CloseableHttpAsyncClient buildSharedClient(String userAgent, HttpConfig httpConfig, @Nullable Predicate<TrustManagerParameters> trustManagerParametersPredicate,
82:     ProxySelector proxySelector, CredentialsProvider proxyCredentialsProvider, int maxRetries, int retryInterval) {
83:     var asyncConnectionManager = PoolingAsyncClientConnectionManagerBuilder.create()
84:       .setTlsStrategy(new DefaultClientTlsStrategy(configureSsl(httpConfig.sslConfig(), trustManagerParametersPredicate)))
85:       .setDefaultTlsConfig(TlsConfig.custom()
86:         // Force HTTP/1 since we know SQ/SC don't support HTTP/2 ATM
87:         .setVersionPolicy(HttpVersionPolicy.FORCE_HTTP_1)
88:         .build())
89:       .setDefaultConnectionConfig(buildConnectionConfig(httpConfig.connectTimeout(), httpConfig.socketTimeout()))
90:       .build();
91:     var routePlanner = new SystemDefaultRoutePlanner(proxySelector);
92:     return HttpAsyncClients.custom()
93:       .setConnectionManager(asyncConnectionManager)
94:       .addResponseInterceptorFirst(new RedirectInterceptor())
95:       .setUserAgent(userAgent)
96:       // proxy settings
97:       .setRoutePlanner(routePlanner)
98:       .setDefaultCredentialsProvider(proxyCredentialsProvider)
99:       .setDefaultRequestConfig(buildRequestConfig(httpConfig.connectionRequestTimeout(), httpConfig.responseTimeout()))
100:       .setRetryStrategy(new RetryOnDemandStrategy(maxRetries, TimeValue.ofSeconds(retryInterval)))
101:       .build();
102:   }
103: 
104:   private static SSLContext configureSsl(SslConfig sslConfig, @Nullable Predicate<TrustManagerParameters> trustManagerParametersPredicate) {
105:     var sslFactoryBuilder = SSLFactory.builder()
106:       .withDefaultTrustMaterial();
107:     // SLCORE-686; SLCORE-669
108:     if (isNotWindows()) {
109:       sslFactoryBuilder.withSystemTrustMaterial();
110:     }
111:     var keyStore = sslConfig.getKeyStore();
112:     if (keyStore != null && Files.exists(keyStore.getPath())) {
113:       try {
114:         sslFactoryBuilder.withIdentityMaterial(keyStore.getPath(), keyStore.getKeyStorePassword().toCharArray(), keyStore.getKeyStoreType());
115:       } catch (Exception e) {
116:         LOG.warn("Unable to load key store from '{}', it will be ignored: {}", keyStore.getPath(), e.getMessage());
117:       }
118:     }
119:     var trustStore = sslConfig.getTrustStore();
120:     if (trustStore != null) {
121:       try {
122:         sslFactoryBuilder.withInflatableTrustMaterial(trustStore.getPath(), trustStore.getKeyStorePassword().toCharArray(),
123:           trustStore.getKeyStoreType(), trustManagerParametersPredicate);
124:       } catch (Exception e) {
125:         LOG.warn("Unable to load trust store from '{}', it will be ignored: {}", trustStore.getPath(), e.getMessage());
126:       }
127:     }
128:     return sslFactoryBuilder.build().getSslContext();
129:   }
130: 
131:   private static boolean isNotWindows() {
132:     return !SystemUtils.IS_OS_WINDOWS;
133:   }
134: 
135:   private static ConnectionConfig buildConnectionConfig(@Nullable Timeout connectTimeout, @Nullable Timeout socketTimeout) {
136:     var connectionConfig = ConnectionConfig.custom();
137:     if (connectTimeout != null) {
138:       connectionConfig.setConnectTimeout(connectTimeout);
139:     }
140:     if (socketTimeout != null) {
141:       connectionConfig.setSocketTimeout(socketTimeout);
142:     }
143:     return connectionConfig.build();
144:   }
145: 
146:   private static RequestConfig buildRequestConfig(@Nullable Timeout connectionRequestTimeout, @Nullable Timeout responseTimeout) {
147:     var requestConfig = RequestConfig.custom()
148:       .setContentCompressionEnabled(false);
149:     if (connectionRequestTimeout != null) {
150:       requestConfig.setConnectionRequestTimeout(connectionRequestTimeout);
151:     }
152:     if (responseTimeout != null) {
153:       requestConfig.setResponseTimeout(responseTimeout);
154:     }
155:     return requestConfig.build();
156:   }
