65:     // in theory all clients bundle SonarJS, so this should always return true
66:     // in practice and to speed up tests, we will avoid looking up Node.js if SonarJS is not present
67:     var languagesNeedingNodeJsInSonarJs = SonarPlugin.JS.getLanguages().stream().map(l -> Language.valueOf(l.name())).collect(Collectors.toSet());
68:     return !Collections.disjoint(initializeParams.getEnabledLanguagesInStandaloneMode(), languagesNeedingNodeJsInSonarJs)
69:       || !Collections.disjoint(initializeParams.getExtraEnabledLanguagesInConnectedMode(), languagesNeedingNodeJsInSonarJs);
