42:   private final System2 system2;
43:   private final Path pathHelperLocationOnMac;
44:   private final CommandExecutor commandExecutor;
45: 
46:   public NodeJsHelper() {
47:     this(System2.INSTANCE, Paths.get("/usr/libexec/path_helper"), CommandExecutor.create());
48:   }
49: 
50:   // For testing
51:   NodeJsHelper(System2 system2, Path pathHelperLocationOnMac, CommandExecutor commandExecutor) {
52:     this.system2 = system2;
53:     this.pathHelperLocationOnMac = pathHelperLocationOnMac;
54:     this.commandExecutor = commandExecutor;
55:   }
