57:   @CheckForNull
58:   public InstalledNodeJs autoDetect() {
59:     return detect(null);
60:   }
61: 
62:   @CheckForNull
63:   public InstalledNodeJs detect(@Nullable Path configuredNodejsPath) {
64:     var detectedNodePath = locateNode(configuredNodejsPath);
65:     if (detectedNodePath != null) {
66:       var nodeJsVersion = readNodeVersion(detectedNodePath);
67:       if (nodeJsVersion == null) {
68:         LOG.warn("Unable to query node version");
69:       } else {
70:         return new InstalledNodeJs(detectedNodePath, nodeJsVersion);
71:       }
72:     }
73:     return null;
74:   }
