76:   @CheckForNull
77:   private Version readNodeVersion(Path detectedNodePath) {
78:     LOG.debug("Checking node version...");
79:     String nodeVersionStr;
80:     var forcedNodeVersion = System.getProperty("sonarlint.internal.nodejs.forcedVersion");
81:     if (forcedNodeVersion != null) {
82:       nodeVersionStr = forcedNodeVersion;
83:     } else {
84:       var command = Command.create(detectedNodePath.toString()).addArgument("-v");
85:       nodeVersionStr = runSimpleCommand(command);
86:     }
87:     Version nodeJsVersion = null;
88:     if (nodeVersionStr != null) {
89:       var matcher = NODEJS_VERSION_PATTERN.matcher(nodeVersionStr);
90:       if (matcher.matches()) {
91:         var version = matcher.group(1);
92:         nodeJsVersion = Version.create(version);
93:         LOG.debug("Detected node version: {}", nodeJsVersion);
94:       } else {
95:         LOG.debug("Unable to parse node version: {}", nodeVersionStr);
96:       }
97:     }
98:     return nodeJsVersion;
99:   }
