101:   @CheckForNull
102:   private Path locateNode(@Nullable Path configuredNodejsPath) {
103:     if (configuredNodejsPath != null) {
104:       LOG.debug("Node.js path provided by configuration: {}", configuredNodejsPath);
105:       return configuredNodejsPath;
106:     }
107:     LOG.debug("Looking for node in the PATH");
108: 
109:     var forcedPath = System.getProperty("sonarlint.internal.nodejs.forcedPath");
110:     String result;
111:     if (forcedPath != null) {
112:       result = forcedPath;
113:     } else if (system2.isOsWindows()) {
114:       result = runSimpleCommand(Command.create("C:\\Windows\\System32\\where.exe").addArgument("$PATH:node.exe"));
115:     } else {
116:       // INFO: Based on the Linux / macOS shell we require the full path as "which" is a built-in on some shells!
117:       var which = Command.create("/usr/bin/which").addArgument("node");
118:       computePathEnvForMacOs(which);
119:       result = runSimpleCommand(which);
120:     }
121:     if (result != null) {
122:       LOG.debug("Found node at {}", result);
123:       return Paths.get(result);
124:     } else {
125:       LOG.debug("Unable to locate node");
126:       return null;
127:     }
128:   }
129: 
130:   private void computePathEnvForMacOs(Command which) {
131:     if (system2.isOsMac() && Files.exists(pathHelperLocationOnMac)) {
132:       var command = Command.create(pathHelperLocationOnMac.toString()).addArgument("-s");
133:       var pathHelperOutput = runSimpleCommand(command);
134:       if (pathHelperOutput != null) {
135:         var regex = Pattern.compile("^\\s*PATH=\"([^\"]+)\"; export PATH;?\\s*$");
136:         var matchResult = regex.matcher(pathHelperOutput);
137:         if (matchResult.matches()) {
138:           which.setEnvironmentVariable("PATH", matchResult.group(1));
139:         }
140:       }
141:     }
142:   }
143: 
144:   /**
145:    * Run a simple command that should return a single line on stdout
146:    */
147:   @CheckForNull
148:   private String runSimpleCommand(Command command) {
149:     List<String> stdOut = new ArrayList<>();
150:     List<String> stdErr = new ArrayList<>();
151:     LOG.debug("Execute command '{}'...", command);
152:     int exitCode;
153:     try {
154:       exitCode = commandExecutor.execute(command, stdOut::add, stdErr::add, 10_000);
155:     } catch (CommandException e) {
156:       LOG.debug("Unable to execute the command", e);
157:       return null;
158:     }
159:     var msg = new StringBuilder(String.format("Command '%s' exited with %s", command, exitCode));
160:     if (!stdOut.isEmpty()) {
161:       msg.append("\nstdout: ").append(String.join("\n", stdOut));
162:     }
163:     if (!stdErr.isEmpty()) {
164:       msg.append("\nstderr: ").append(String.join("\n", stdErr));
165:     }
166:     LOG.debug("{}", msg);
167:     if (exitCode != 0 || stdOut.isEmpty()) {
168:       return null;
169:     }
170:     return stdOut.get(0);
171:   }
