40: public class NativeGit {
41:   private static final SonarLintLogger LOG = SonarLintLogger.get();
42:   private static final Version MINIMUM_REQUIRED_GIT_VERSION = Version.create("2.24");
43:   private static final String GIT_VERSION_OUTPUT_PREFIX = "git version";
44:   private static final Period BLAME_HISTORY_WINDOW = Period.ofDays(365);
45:   private final String executable;
46: 
47:   public NativeGit(String executable) {
48:     this.executable = executable;
49:   }
50: 
51:   public boolean isSupportedVersion() {
52:     return version()
53:       .filter(version -> version.satisfiesMinRequirement(MINIMUM_REQUIRED_GIT_VERSION))
54:       .isPresent();
55:   }
56: 
57:   private Optional<Version> version() {
58:     var lines = new ArrayList<String>();
59:     var success = executeGitCommand(null, lines::add, executable, "--version");
60:     return success ? parseGitVersionOutput(lines) : Optional.empty();
61:   }
62: 
63:   static Optional<Version> parseGitVersionOutput(List<String> lines) {
64:     var version = lines.stream().findFirst()
65:       .map(String::trim)
66:       .filter(line -> line.startsWith(GIT_VERSION_OUTPUT_PREFIX))
67:       .map(line -> line.substring(GIT_VERSION_OUTPUT_PREFIX.length()))
68:       .map(String::trim)
69:       .map(actualVersion -> actualVersion.split("\\.", 3))
70:       .filter(versionParts -> versionParts.length > 1)
71:       .flatMap(NativeGit::tryCreateVersion);
72:     if (version.isEmpty()) {
73:       LOG.debug("Cannot parse git --version output: {}", String.join("\n", lines));
74:     }
75:     return version;
76:   }
77: 
78:   private static Optional<Version> tryCreateVersion(String[] versionParts) {
79:     try {
80:       // keep only MAJOR and MINOR numbers, it's sufficient for checking support
81:       return Optional.of(Version.create(versionParts[0] + "." + versionParts[1]));
82:     } catch (Exception e) {
83:       // error will be logged above
84:     }
85:     return Optional.empty();
86:   }
