88:   public MultiFileBlameResult blame(Path projectBaseDir, Set<URI> fileUris, Instant thresholdDateFromNewCodeDefinition) {
89:     LOG.debug("Using native git blame");
90:     var startTime = System.currentTimeMillis();
91:     var blamePerFile = new HashMap<String, BlameResult>();
92:     for (var fileUri : fileUris) {
93:       var filePath = FileUtils.getFilePathFromUri(fileUri).toAbsolutePath().toString();
94:       var filePathUnix = filePath.replace("\\", "/");
95:       var yearAgo = Instant.now().minus(BLAME_HISTORY_WINDOW);
96:       var thresholdDate = thresholdDateFromNewCodeDefinition.isAfter(yearAgo) ? yearAgo : thresholdDateFromNewCodeDefinition;
97:       var blameHistoryThresholdCondition = "--since='" + thresholdDate + "'";
98:       var command = new String[] {executable, "blame", blameHistoryThresholdCondition, filePath, "--line-porcelain", "--encoding=UTF-8"};
99:       var blameReader = new GitBlameReader();
100:       var success = executeGitCommand(projectBaseDir, blameReader::readLine, command);
101:       if (success) {
102:         blamePerFile.put(filePathUnix, blameReader.getResult());
103:       }
104:     }
105:     LOG.debug("Blamed {} files in {}ms", fileUris.size(), System.currentTimeMillis() - startTime);
106:     return new MultiFileBlameResult(blamePerFile, projectBaseDir);
107:   }
108: 
109:   private static boolean executeGitCommand(@Nullable Path workingDir, Consumer<String> lineConsumer, String... command) {
110:     var output = new ProcessWrapperFactory()
111:       .create(workingDir, lineConsumer, command)
112:       .execute();
113:     if (output.exitCode() == 0) {
114:       return true;
115:     }
116:     LOG.debug(format("Command failed with code: %d", output.exitCode()));
117:     return false;
118:   }
119: }

