36: public class ExecutableLocator {
37: 
38:   private static final SonarLintLogger LOG = SonarLintLogger.get();
39: 
40:   private final System2 system2;
41:   private final Path pathHelperLocationOnMac;
42:   private final CommandExecutor commandExecutor;
43:   private final NodeJsHelper nodeJsHelper;
44: 
45:   private boolean checkedForExecutable = false;
46:   private HookScriptType detectedExecutable = null;
47: 
48:   public ExecutableLocator() {
49:     this(System2.INSTANCE, Paths.get("/usr/libexec/path_helper"), CommandExecutor.create(), new NodeJsHelper());
50:   }
51: 
52:   // For testing
53:   ExecutableLocator(System2 system2, Path pathHelperLocationOnMac, CommandExecutor commandExecutor, NodeJsHelper nodeJsHelper) {
54:     this.system2 = system2;
55:     this.pathHelperLocationOnMac = pathHelperLocationOnMac;
56:     this.commandExecutor = commandExecutor;
57:     this.nodeJsHelper = nodeJsHelper;
58:   }
59: 
60:   public Optional<HookScriptType> detectBestExecutable() {
61:     if (checkedForExecutable) {
62:       return Optional.ofNullable(detectedExecutable);
63:     }
64: 
65:     // Priority: Node.js > Python > Bash
66:     if (isNodeJsAvailable()) {
67:       LOG.debug("Detected Node.js for hook scripts");
68:       detectedExecutable = HookScriptType.NODEJS;
69:     } else if (isPythonAvailable()) {
70:       LOG.debug("Detected Python for hook scripts");
71:       detectedExecutable = HookScriptType.PYTHON;
72:     } else if (isBashAvailable()) {
73:       LOG.debug("Detected Bash for hook scripts");
74:       detectedExecutable = HookScriptType.BASH;
75:     } else {
76:       LOG.debug("No suitable executable found for hook scripts");
77:       detectedExecutable = null;
78:     }
79: 
80:     checkedForExecutable = true;
81:     return Optional.ofNullable(detectedExecutable);
82:   }
83: 
84:   private boolean isNodeJsAvailable() {
85:     try {
86:       var installedNodeJs = nodeJsHelper.autoDetect();
87:       return installedNodeJs != null;
88:     } catch (Exception e) {
89:       LOG.debug("Error detecting Node.js", e);
90:       return false;
91:     }
92:   }
93: 
94:   private boolean isPythonAvailable() {
95:     // Try python3 first, then python
96:     var python3Path = locatePythonExecutable("python3");
97:     if (python3Path != null) {
98:       return true;
99:     }
100:     var pythonPath = locatePythonExecutable("python");
101:     return pythonPath != null;
102:   }
103: 
104:   @CheckForNull
105:   private String locatePythonExecutable(String executable) {
106:     LOG.debug("Looking for {} in the PATH", executable);
107:     
108:     String result;
109:     if (system2.isOsWindows()) {
110:       result = runSimpleCommand(Command.create("C:\\Windows\\System32\\where.exe").addArgument("$PATH:" + executable + ".exe"));
111:     } else {
112:       var which = Command.create("/usr/bin/which").addArgument(executable);
113:       computePathEnvForMacOs(which);
114:       result = runSimpleCommand(which);
115:     }
116:     
117:     if (result != null) {
118:       LOG.debug("Found {} at {}", executable, result);
119:       return result;
120:     } else {
121:       LOG.debug("Unable to locate {}", executable);
122:       return null;
123:     }
124:   }
125: 
126:   private boolean isBashAvailable() {
127:     if (system2.isOsWindows()) {
128:       // On Windows, try to locate bash.exe (Git Bash, WSL, etc.)
129:       var bashPath = runSimpleCommand(Command.create("C:\\Windows\\System32\\where.exe").addArgument("$PATH:bash.exe"));
130:       return bashPath != null;
131:     } else {
132:       // On Unix/Mac, bash is always available
133:       return Files.exists(Paths.get("/bin/bash"));
134:     }
135:   }
136: 
137:   void computePathEnvForMacOs(Command command) {
138:     if (system2.isOsMac() && Files.exists(pathHelperLocationOnMac)) {
139:       var pathHelperCommand = Command.create(pathHelperLocationOnMac.toString()).addArgument("-s");
140:       var pathHelperOutput = runSimpleCommand(pathHelperCommand);
141:       if (pathHelperOutput != null) {
142:         var regex = Pattern.compile("^\\s*PATH=\"([^\"]+)\"; export PATH;?\\s*$");
143:         var matchResult = regex.matcher(pathHelperOutput);
144:         if (matchResult.matches()) {
145:           command.setEnvironmentVariable("PATH", matchResult.group(1));
146:         }
147:       }
148:     }
149:   }
150: 
151:   @CheckForNull
152:   String runSimpleCommand(Command command) {
153:     var stdOut = new ArrayList<String>();
154:     var stdErr = new ArrayList<String>();
155:     LOG.debug("Execute command '{}'...", command);
156:     int exitCode;
157:     try {
158:       exitCode = commandExecutor.execute(command, stdOut::add, stdErr::add, 10_000);
159:     } catch (CommandException e) {
160:       LOG.debug("Unable to execute the command", e);
161:       return null;
162:     }
163:     var msg = new StringBuilder(String.format("Command '%s' exited with %s", command, exitCode));
164:     if (!stdOut.isEmpty()) {
165:       msg.append("\nstdout: ").append(String.join("\n", stdOut));
166:     }
167:     if (!stdErr.isEmpty()) {
168:       msg.append("\nstderr: ").append(String.join("\n", stdErr));
169:     }
170:     LOG.debug("{}", msg);
171:     if (exitCode != 0 || stdOut.isEmpty()) {
172:       return null;
173:     }
174:     return stdOut.get(0);
175:   }
176: 
177: }
