138:   private Optional<CliParams> prepareCliParams(Binding binding, String configScopeId) {
139:     var connection = connectionConfigurationRepository.getConnectionById(binding.connectionId());
140:     if (connection == null) {
141:       return Optional.empty();
142:     }
143:     var url = connection.getUrl();
144:     var token = getTokenForConnection(binding.connectionId());
145:     if (token.isEmpty()) {
146:       return Optional.empty();
147:     }
148:     var branch = branchTrackingService.awaitEffectiveSonarProjectBranch(configScopeId).orElse(null);
149:     return Optional.of(new CliParams(url, token.get(), binding.sonarProjectKey(), branch));
