152:   private Optional<String> getTokenForConnection(String connectionId) {
153:     try {
154:       var creds = client.getCredentials(new GetCredentialsParams(connectionId)).join().getCredentials();
155:       if (creds != null && creds.isLeft()) {
156:         var tokenDto = creds.getLeft();
157:         return Optional.ofNullable(tokenDto.getToken());
158:       }
159:       return Optional.empty();
160:     } catch (Exception e) {
161:       LOG.debug("Unable to retrieve token for connection '{}'", connectionId, e);
162:       return Optional.empty();
163:     }
